  'settings.mcpRestartDetail': 'பெரும்பாலான எடிட்டர்கள் MCP சேவையகங்களை தொடக்கத்தில் மட்டுமே ஏற்றுகின்றன. Cursor / VS Code / Antigravity / Windsurf-ல் முழு மறுதொடக்கத்திற்கு பதிலாக கட்டளை பலகத்திலிருந்து `Developer: Reload Window`-ஐ இயக்கலாம். Zed மற்றும் Claude Code-க்கு வெளியேறி மறுதொடக்கம் செய்ய வேண்டும்.',
