  'settings.mcpCapabilityRead': 'ஒரு திட்டத்தில் உள்ள எந்தக் கோப்பையும் படி அல்லது தேடு (HTML, JSX, CSS, JSON, SVG, Markdown).',
  'settings.mcpCapabilityPull': 'ஒரு அழைப்பில் ஒரு வடிவமைப்பு மூட்டையை இழு: நுழைவுக் கோப்பு மற்றும் அது குறிப்பிடும் ஒவ்வொரு CSS மாறி, கூறு, எழுத்துரு.',
  'settings.mcpCapabilityDefault': 'Open Design-ல் நீங்கள் திறந்துள்ள திட்டம் மற்றும் கோப்பிற்கு இயல்புநிலை, இதனால் எந்த வடிவமைப்பை மீண்டும் கூறாமல் "என் செயலில் இதை உருவாக்கு" எனச் சொல்ல முடியும்.',
  'settings.mcpRunningNote': 'MCP கருவி அழைப்புகள் வெற்றிபெற Open Design இயங்கிக்கொண்டிருக்க வேண்டும். Open Design-ஐத் திறப்பதற்கு முன் உங்கள் கோடிங் முகவரைத் தொடங்கியிருந்தால், நேரடி டெமானை அடைய முகவரை மறுதொடக்கம் செய்யவும்.',
