  'handoff.promptProduceCode': 'உண்மையான இயங்கக்கூடிய {framework} கோடினை உருவாக்கு அல்லது மாற்று. திட்டத்திற்கு ஏற்கனவே தெளிவான ஸ்டாக் இருந்தால், முரண்பாட்டைச் சுட்டிக்காட்டி முடிவை இயங்கக்கூடியதாக வைக்கவும்.',
