  'chat.brandBrowserAssistDesktopOnly': 'Browser assist-க்குத் தேவையான டெஸ்க்டாப் ஆப் வேண்டும், அப்போதுதான் Open Design நேரடி பிரவுசர் பக்கத்தைப் படிக்க முடியும்.',
  'chat.brandBrowserAssistReadFailed': 'பிரவுசர் பக்கத்தைப் படிக்க முடியவில்லை. பிராண்ட் தளம் திறந்திருக்கிறதா மற்றும் முழுமையாக ஏற்றப்பட்டிருக்கிறதா என உறுதி செய்யவும்.',
  'chat.brandBrowserAssistMessage': 'இந்தப் பிராண்டு எடுத்தெடுப்பை முடிக்க Open Design-க்கு browser assist தேவைப்படுகிறது. Browser தாவலில் பக்கத்தை அழித்துவிட்டு, கீழே உறுதிசெய்யவும்.',
  'brandEnrichment.title': 'AI Optimize',
  'brandEnrichment.body': 'Open Design பின்னணியில் ஆழமான எடுத்தெடுப்பை இயக்கும், சரியான design-system ஸ்கில்களைத் தானாகப் பயன்படுத்தும், இந்த அமைப்பை இடத்திலேயே புதுப்பிக்கும். இதற்கு 10-20 நிமிடங்கள் ஆகலாம்; நீங்கள் வேலை செய்துகொண்டே இருக்கலாம்.',
  'brandEnrichment.cta': 'AI Optimize',
