  'brandExtractionTranscript.sourceDesignMd': 'ஒட்டப்பட்ட DESIGN.md',
  'brandExtractionTranscript.user': '{source}-இலிருந்து ஒரு design system-ஐ எடுத்தெடுக்கவும்.',
  'brandExtractionTranscript.doneTitle': '{name}-க்கான நிரல்முறை எடுத்தெடுப்பு முடிந்தது.',
  'brandExtractionTranscript.doneBody': 'நான் {designSystemId} design system-ஐ {source}-இலிருந்து உருவாக்கிப் பதிவுசெய்தேன். இது முன்னோட்டம் காணத் தயாராக உள்ளது மற்றும் இப்போது புதிய வடிவமைப்புகளில் பயன்படுத்தலாம்.',
  'brandExtractionTranscript.next': 'அடுத்ததாக, ஒரு தொடர்செயலைத் தேர்வுசெய்யவும்: மாதிரி டோக்கன்களைப் பயன்படுத்தும் agent pass மூலம் எடுக்கப்பட்ட design system-ஐச் சீர்செய்யவும், அல்லது இந்த அமைப்பைப் பயன்படுத்தி புதிய வடிவமைப்பை உருவாக்கவும்.',
