  'chat.designToolbox.prompt.referenceDesignFiles': 'குறிப்பு வடிவமைப்பு கோப்புகள்',
  'chat.designToolbox.prompt.mcpTemplateName': '{name} டெம்ப்ளேட்',
  'chat.designToolbox.prompt.processRule': 'பணிப்பாய்வு விதி: முதலில் அழகியல் இலக்கு மற்றும் கட்டுப்பாடுகளை வரையறு, பிறகு வளங்களைத் தேடி பொருத்து; பயனர் தேர்வு தேவைப்படும்போது, ஒரு வரையறுக்கப்பட்ட-தேர்வு UI-ஐ உருவாக்கி, உறுதிப்படுத்தலுக்குப் பிறகு தொடர்.',
