  'chat.example1Title': 'எடிட்டோரியல் விளக்கக்காட்சி ஸ்லைடு ஸ்லைடு',
  'chat.example1Tag': 'Magazine',
  'chat.example1Prompt': 'ஒரு வடிவமைப்பு ஸ்டுடியோவிற்கான seed சுற்று திரட்டும் 10-ஸ்லைடு எடிட்டோரியல் விளக்கக்காட்சி ஸ்லைடு ஸ்லைடு — Swiss-grid தளவமைப்பு, bold drop caps உடன் oversized serif headlines, monospace section எண்கள், தாராளமான எதிர்மறை இடம், மற்றும் உரை-நிறைந்த ஸ்லைடுகளுடன் கலந்த full-bleed photo ஸ்லைடுகள். Cover, vision, market, product, traction, team, ask, contact.',
  'chat.example2Title': 'SaaS பகுப்பாய்வு டாஷ்போர்டு',
  'chat.example2Tag': 'தரவு',
  'chat.example2Prompt': 'ஒரு developer-tools SaaS-க்கான அடர்ந்த பகுப்பாய்வு டாஷ்போர்டு — week-over-week deltas உடன் KPI strip, இரண்டு அடுக்கப்பட்ட line charts (MRR மற்றும் active workspaces), பயன்பாட்டின் உலக heatmap, ஒரு cohort retention grid, ஒரு top-customers leaderboard, மற்றும் real-time event feed. இருண்ட theme, tabular monospace numerals, sparkline accents.',
  'chat.example3Title': 'ஆண்டு அறிக்கை long-scroll',
  'chat.example3Tag': 'எடிட்டோரியல்',
  'chat.example3Prompt': 'ஒரு காலநிலை இலாப நோக்கற்ற நிறுவனத்திற்கான interactive ஆண்டு அறிக்கை — பெரிய pull-quote blocks, தரவு visualizations (stacked bars, animated counters, திட்ட தளங்களின் choropleth map), photography breakers, donor wall, மற்றும் இறுதி call-to-action ஆகியவற்றை கலக்கும் long-scroll எடிட்டோரியல் தளவமைப்பு. நவீன serif உடல், sans-serif chart labels, earthy paper palette.',
