  'designFiles.usefulInfoLabel': 'பயனுள்ள தகவல்',
  'designFiles.usefulInfoTip': 'ஒரு கோப்பை முழு தாவலில் திற்க இரட்டை-கிளிக் செய்.',
  'designFiles.usefulInfoTip2': 'ஒரு கோப்பைச் சூழலாகக் குறிப்பிட அரட்கையில் @ தட்டச்சு செய்.',
  'designFiles.usefulInfoTip4': 'உருவாக்கப்பட்ட வடிவமைப்புகளை brand-இல் வைக்க ஒரு வடிவமைப்பு அமைப்பைத் தேர்ந்தெடு.',
  'designFiles.usefulInfoTip5': 'யோசனைகள் தீர்ந்துவிட்டதா? முகப்பு பக்கத்தில் Community-இலிருந்து ஒரு செருகுநிரல் டெம்ப்ளேட்டை முயற்சி செய்.',
  'designFiles.usefulInfoTip6': 'கேள்விகள் அல்லது கருத்துகளா? Discord-ல் எங்களுடன் சேர்.',
  'designFiles.usefulInfoTip7': 'Open Design பிடித்திருக்கிறதா? GitHub-ல் எங்களுக்கு star செய்.',
  'designFiles.usefulInfoTip8': 'சமீபத்திய புதுப்பிப்புகளுக்கு X-ல் @nexudotio-ஐப் பின்தொடரு.',
  'designFiles.usefulInfoTip9': 'படங்கள், ஆவணங்கள், அல்லது முழு கோப்புறைகளை இந்தப் பலகத்திற்குள் இழுத்துச் செல் — முகவர் அவற்றைச் சூழலாகப் பயன்படுத்துகிறார்.',
  'designFiles.usefulInfoTip10': 'ஒரு கரடுமுரடான தளவமைப்பை வரைய புதிய ஸ்கெட்ச்-ஐ கிளிக் செய்து முகவரை அதிலிருந்து கட்டச் சொல்.',
  'designFiles.usefulInfoTip11': 'கருத்து தெரிவிக்க முன்னோட்டத்தில் ஏதேனும் ஒரு உறுப்பைத் தேர்ந்தெடு — முகவர் குறிவைத்த திருத்தங்களைச் செய்கிறார்.',
  'designFiles.usefulInfoTip12': 'ஒரு முடிவில் திருப்தி இல்லையா? முன்னோட்டத்தில் அதை வட்டமிடுவது மறு-விவரிப்பதை விட சிறந்தது.',
  'designFiles.usefulInfoTip13': 'எந்த வடிவமைப்பையும் ஒரு கிளிக்கில் PDF, படம், அல்லது standalone HTML ஆக ஏற்றுமதி செய்.',
  'designFiles.usefulInfoTip14': 'ஒரு திட்டத்தில் திருப்தியா? அதை Share மெனுவிலிருந்து டெம்ப்ளேட்டாகச் சேமித்து எப்போது வேண்டுமானாலும் மறுபயன்பாடு செய்.',
  'designFiles.usefulInfoTip15': 'டெப்லாய் செய்த பிறகு, ஒரே படியில் சமூக பகிர் அட்டைகளை உருவாக்கு.',
