  'pet.idleQuote.leonardo.text': 'கற்றல் மனதை ஒருபோதும் சோர்வடையச் செய்யாது.',
  'pet.idleQuote.leonardo.author': 'Leonardo da Vinci',
  'pet.idleQuote.michelangelo.text': 'பளபளப்புக் கல்லில் தேவதையை நான் கண்டேன், அவளை விடுவிக்கும் வரை செதுக்கினேன்.',
