  'pet.idleQuote.bernini.text': 'சிற்பிக்கு உதவக்கூடிய இரண்டு கருவிகள் உள்ளன: ஒளியும் நிழலும்.',
  'pet.idleQuote.bernini.author': 'Gian Lorenzo Bernini',
  'pet.idleQuote.raphael.text': 'ஒருவர் ஓவியம் வரையும்போது அவர் சிந்திப்பதில்லை.',
  'pet.idleQuote.raphael.author': 'Raphael',
  'pet.idleQuote.caravaggio.text': 'எல்லா படைப்புகளும், எது எப்படி அல்லது யாரால் வரையப்பட்டதாயினும், வாழ்க்கையிலிருந்து உருவாக்கப்பட்டு வரையப்படாவிட்டால் வெறும் சிறுவிளையாட்டுகளே.',
  'pet.idleQuote.caravaggio.author': 'Caravaggio',
  'pet.idleQuote.rodin.text': 'முக்கியமானது உணர்வது, நேசிப்பது, நம்புவது, நடுங்குவது, வாழ்வது.',
  'pet.idleQuote.rodin.author': 'Auguste Rodin',
