  'settings.connectorsClearConfirmBody': 'key-ஐ அகற்றுவது இந்தப் பணியிடத்துடன் இணைக்கப்பட்ட ஒவ்வொரு Composio இணைப்பியையும் துண்டிக்கிறது. இணைக்கப்பட்ட கணக்குகள், OAuth grants மற்றும் கருவி அணுகல் அனைத்தும் அகற்றப்படும்.',
