  'settings.libraryToggleLabel': 'Toggle',
  'settings.memory': 'நினைவு',
  'settings.memoryHint': 'எதிர்கால அரட்கைகளுக்கான சேமிக்கப்பட்ட உண்மைகள் மற்றும் சூழல்',
  'settings.customInstructionsTitle': 'உலகளாவிய விதிகள்',
  'settings.customInstructionsHint': 'OpenDesign ஒவ்வொரு அரட்கையிலும் பின்பற்ற வேண்டிய நிலையான அறிவுறுத்தல்கள். உண்மைகள், விருப்பத்தேர்வுகள் மற்றும் திட்டச் சூழலை memories ஆகச் சேமி.',
  'settings.customInstructionsPlaceholder': 'எ.கா. "எப்போதும் TypeScript பயன்படுத்து. செயல்பாட்டு components விரும்பு. பதில்களைச் சுருக்கமாக வை."',
  'settings.memoryDescription': 'சேமிக்கப்பட்ட உண்மைகள், விருப்பத்தேர்வுகள் மற்றும் திட்டச் சூழல் எதிர்கால அரட்கைகளில் மறுபயன்பாடு செய்யப்படுகிறதா என்பதைக் கட்டுப்படுத்து.',
  'settings.memoryEnabled': 'இயக்கப்பட்டது',
  'settings.memoryDisabled': 'முடக்கப்பட்டது',
  'settings.memoryEnableLabel': 'நினைவு செலுத்தலை இயக்கு',
  'settings.memoryDisabledBanner': 'நினைவு தற்போது அணை. ஏற்கனவே உள்ள உண்மைகள் வட்டில் பாதுகாக்கப்படுகின்றன ஆனால் புதிய அரட்கைகளில் சேர்க்கப்படமாட்டாது மற்றும் புதிய முறைகள் எதையும் பிரித்தெடுக்காது.',
  'settings.memoryNew': 'புதிய நினைவு',
  'settings.memoryEdit': 'திருத்து',
  'settings.memoryDelete': 'நீக்கு',
  'settings.memoryPreview': 'முன்னோட்டம்',
  'settings.memoryEmpty': 'இன்னும் நினைவு இல்லை.',
  'settings.memoryEmptyHintZh': '记住: 用户偏好深色主题',
  'settings.memoryEmptyHintEn': 'நான் இருண்ட பயன்முறையை விரும்புகிறேன்',
  'settings.memoryName': 'எ.கா. UI விருப்பத்தேர்வுகள்',
  'settings.memoryDesc': 'ஒரு வாக்கியம் — இந்த நினைவு பற்றி என்ன?',
  'settings.memoryBody': '- விதி ஒன்று\n- விதி இரண்டு\n\nஏன்: விருப்பப்பட்ட காரணம்\nஎப்போது பயன்படுத்துவது: விருப்பப்பட்ட scope',
  'settings.memoryBodyHint': 'முதலில் விதிகளை bullet செய், பிறகு விருப்பப்பட்ட ஏன் மற்றும் எப்போது-பயன்படுத்துவது வரிகள். Markdown ஆதரிக்கப்படுகிறது. அல்லது ஒரு வேலை செய்யும் உதாரணத்தை ஏற்ற மேலே உள்ள starter-ஐ கிளிக் செய்.',
  'settings.memoryStartersLabel': 'ஒரு தொடக்க புள்ளி தேவையா? படிவத்தை நிரப்ப கிளிக் செய்:',
  'settings.memoryStarterUserName': 'என் பங்கு',
  'settings.memoryStarterUserDesc': 'நான் ஒரு SaaS வடிவமைப்பு கருவியில் வேலை செய்யும் ஒரு frontend engineer',
  'settings.memoryStarterUserBody': '- பங்கு: senior frontend engineer\n- Stack: React, TypeScript, Vite\n- Domain: வடிவமைப்பு / ஒத்துழைப்பு கருவிகள்\n- Timezone: GMT+8 (Asia/Shanghai)\n\nஎப்போது பயன்படுத்துவது: எந்த அரட்கை — உதாரணங்களை web frontend-ஐ சுற்றி வடிவமை.',
  'settings.memoryStarterFeedbackName': 'UI விருப்பத்தேர்வுகள்',
  'settings.memoryStarterFeedbackDesc': 'இருண்ட பயன்முறை, பெரிய body உரை, குறைந்த தகவல் அடர்த்தி',
  'settings.memoryStarterFeedbackBody': '- Theme: இயல்புநிலையாக இருண்டது\n- Body உரை: ≥ 18px\n- தகவல் அடர்த்தி: whitespace விரும்பு, ஒரு திரைக்கு குறைவான உருப்படிகள்\n\nஏன்: நீண்ட அமர்வுகளின் போது குறைந்த கண் அழுத்தம்.\nஎப்போது பயன்படுத்துவது: நீங்கள் UI, வலை பக்கங்கள், அல்லது ஸ்லைடுகளை உருவாக்கும்போது.',
  'settings.memoryStarterProjectName': 'தற்போதைய திட்டம்',
  'settings.memoryStarterProjectDesc': 'Open Design v0.5 — அரட்கை-இயக்கப்பட்ட வடிவமைப்பு திருத்தி',
  'settings.memoryStarterProjectBody': '- இலக்கு: இந்த காலாண்டில் அரட்கை-இயக்கப்பட்ட திருத்தியை வழங்கு\n- முன்னுரிமைகள்: streaming render, உள்ளமை multimodal, offline-first\n- Stack: Next.js 16, Express daemon, SQLite\n\nஎப்போது பயன்படுத்துவது: இந்த திட்டத்தைப் பற்றிய எந்த உரையாடலிலும்.',
  'settings.memorySaveHint': 'தானாக சேமிக்கப்படாது — பயன்படுத்து Create / Save-ஐ கிளிக் செய்.',
  'settings.memoryIndexSaveHint': 'index-க்கான திருத்தங்கள் தானாக சேமிக்கப்படாது — பயன்படுத்து Save index-ஐ கிளிக் செய்.',
