  'settings.memoryProfileHint': 'உங்களைப் பற்றிய சில தகவல்கள் மற்றும் உங்கள் இயல்புநிலைகள். ஒவ்வொரு பணிக்கும் முன் நினைவகம் இதைச் செருகுவதால், சுருக்கமான கோரிக்கையிலிருந்தே முகவர் உங்கள் பொருளைப் புரிந்துகொள்கிறார்.',
