  'settings.customInstructionsDesc': 'Open Design ஒவ்வொரு அரட்கையிலும் பின்பற்றும் நிலையான அறிவுறுத்தல்கள். இவை சேமிக்கப்பட்ட நினைவுகள் அல்ல; உண்மைகள், விருப்பத்தேர்வுகள், மற்றும் திட்ட சூழலுக்கு நினைவைப் பயன்படுத்து.',
