  'mcpClient.forwardedAcpNote': 'stdio என குறிக்கப்பட்ட ACP adapters இந்த பட்டியலிலிருந்து வெறும் stdio MCP சேவையகங்களை மட்டுமே பெறுகின்றன; HTTP மற்றும் SSE உள்ளீடுகள் spawn நேரத்தில் கைவிடப்படுகின்றன.',
  'mcpClient.notForwardedNote': 'அந்த முகவர்களுக்கு, MCP சேவையகங்களை முகவரின் சொந்த உள்ளமை கோப்பில் உள்ளமை (எ.கா. ~/.codex/config.toml, ~/.gemini/settings.json); கீழே உள்ள சேவையகங்கள் அங்கு அமைதியாக பயன்படுத்தப்படாது.',
