  'onboarding.brandSubtitle': 'ஒரு வலைத்தளத்தை ஒட்டவும்; அதன் பிராண்டு சமிக்ஞைகளை எதிர்கால வேலைக்கு மீண்டும் பயன்படுத்தக்கூடிய வடிவமைப்பு அமைப்பாக நாங்கள் மாற்றுவோம்.',
