  'onboarding.buildTitle': 'ஒருமுறை உருவாக்கு, எல்லா இடங்களிலும் கட்டு',
  'onboarding.buildBody': 'Open Design உங்கள் பிராண்டை மீண்டும் பயன்படுத்தக்கூடிய வடிவமைப்பு அமைப்பாக மாற்றுகிறது — பிறகு நீங்கள் உருவாக்கும் ஒவ்வொரு விஷயத்தையும் பிராண்டுக்கு இணையாகவும் சீராகவும் வைத்திருக்கிறது.',
  'onboarding.buildBenefitMemoryTitle': 'ஒரே பிராண்டு நினைவு',
  'onboarding.buildBenefitMemoryBody': 'வண்ணங்கள், எழுத்துரு, இடைவெளி, கூறுகள், குரல் ஆகியவை உங்கள் முகவர்கள் மீண்டும் பயன்படுத்தக்கூடிய ஒரு DESIGN.md ஆக மாறுகின்றன.',
  'onboarding.buildBenefitAlignedTitle': 'ஒவ்வொரு வெளியீடும் இணைந்தே இருக்கும்',
  'onboarding.buildBenefitAlignedBody': 'மாதிரி, ஸ்லைடு, PDF, டாஷ்போர்டு, சந்தைப்படுத்தல் வேலைகள் அனைத்தும் ஒரே விதிகளிலிருந்து எடுக்கப்படுகின்றன.',
  'onboarding.buildBenefitSourcesTitle': 'உங்களிடம் உள்ளதிலிருந்து தொடங்குங்கள்',
  'onboarding.buildBenefitSourcesBody': 'GitHub களஞ்சியம், வலைத்தளம், ஏற்கனவே உள்ள DESIGN.md, ஸ்கிரீன்ஷாட்கள், எழுத்துருக்கள் அல்லது Figma கோப்புகளைப் பயன்படுத்துங்கள்.',
  'onboarding.buildPreviewLabel': 'பிராண்டு அமைப்பு',
