  'dsCreate.sourceSectionTitle': 'GitHub, வலைத்தளங்கள் அல்லது மூலப் பொருட்களிலிருந்து பிரித்தெடு',
  'dsCreate.sourceSectionBody': 'ஒரு GitHub களஞ்சியம், வலைத்தளம், DESIGN.md அல்லது உங்கள் பாணியைக் காட்டும் கோப்புகளுடன் தொடங்கவும். Open Design முதலில் பயன்படுத்தக்கூடிய ஒரு அமைப்பை விரைவாக உருவாக்குகிறது, பிறகு AI அதை திட்டத்திற்குள் மேம்படுத்தலாம்.',
